  const costs = new Map()
  const declaredAt = new Map()
  const depSets = new Map()
  // Every name a `dep` line uses, in input order, so an unknown one can be
  // reported in that same order once the whole input has been read.
  const references = []

  const lines = splitLines(text)
  for (let i = 0; i < lines.length; i += 1) {
    const lineNo = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const words = line.split(/\s+/)
    const directive = words[0]

