      if (words.length !== 3) {
        throw new InputError(`error: line ${lineNo}: expected task <name> <cost>`)
      }
      const [, name, cost] = words
      if (!isValidName(name)) {
        throw new InputError(`error: line ${lineNo}: invalid task name ${name}`)
      }
      if (!COST_RE.test(cost)) {
        throw new InputError(`error: line ${lineNo}: cost must be a non-negative integer`)
      }
      if (declaredAt.has(name)) {
        throw new InputError(`error: line ${lineNo}: task ${name} is declared twice`)
      }
      declaredAt.set(name, lineNo)
      costs.set(name, Number(cost))
      if (!depSets.has(name)) depSets.set(name, new Set())
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new InputError(`error: line ${lineNo}: expected dep <name> <dependency>...`)
      }
      for (let w = 1; w < words.length; w += 1) {
        if (!isValidName(words[w])) {
          throw new InputError(`error: line ${lineNo}: invalid task name ${words[w]}`)
        }
      }
