      for (let w = 1; w < words.length; w += 1) references.push(words[w])
      if (!depSets.has(subject)) depSets.set(subject, new Set())
      const set = depSets.get(subject)
      for (let w = 2; w < words.length; w += 1) set.add(words[w])
    } else {
      throw new InputError(`error: line ${lineNo}: unknown directive ${directive}`)
    }
  }

  for (const name of references) {
    if (!costs.has(name)) throw new InputError(`error: unknown task ${name}`)
  }

