{"file_path":"src/schedule.js","content":"/**
 * Analysis of a parsed build graph: cycles, depths, critical-path times and
 * the greedy list schedule used by `pack`.
 */

import { compareNames } from './parse.js'

/**
 * The first cycle a depth-first search finds when it starts from each task in
 * ascending name order and walks each task's dependencies in ascending name
 * order, as the names from the re-entered task through the search stack and
 * back to it. Returns `null` when the graph is acyclic.
 */
export function findCycle(names, deps) {
  const WHITE = 0
  const GREY = 1
  const BLACK = 2
  const colour = new Map(names.map((name) => [name, WHITE]))

  for (const root of names) {
    if (colour.get(root) !== WHITE) continue
    const path = [root]
    const frames = [{ node: root, next: 0 }]
    colour.set(root, GREY)
    while (frames.length > 0) {
      const frame = frames[frames.length - 1]
      const edges = deps.get(frame.node)
      if (frame.next < edges.length) {
        const next = edges[frame.next]
        frame.next += 1
        const state = colour.get(next)
        if (state === GREY) {
          return [...path.slice(path.indexOf(next)), next]
        }
        if (state === WHITE) {
          colour.set(next, GREY)
          path.push(next)
          frames.push({ node: next, next: 0 })
        }
      } else {
        colour.set(frame.node, BLACK)
        path.pop()
        frames.pop()
      }
    }
  }
  return null
}

/** Ascending name order with every dependency before its dependent. */
export function topologicalOrder(names, deps) {
  const order = []
  const seen = new Set()
  const visit = (name) => {
    const stack = [{ node: name, next: 0 }]
    seen.add(name)
    while (stack.length > 0) {
      const frame = stack[stack.length - 1]
      const edges = deps.get(frame.node)
      if (frame.next < edges.length) {
        const next = edges[frame.next]
        frame.next += 1
        if (!seen.has(next)) {
          seen.add(next)
          stack.push({ node: next, next: 0 })
        }
      } else {
        order.push(frame.node)
        stack.pop()
      }
    }
  }
  for (const name of names) if (!seen.has(name)) visit(name)
  return order
}

/**
 * The unlimited-worker times: `depth`, `start` and `finish` per task, plus the
 * makespan `total` (0 when there is no task).
 */
export function analyse(graph) {
  const { names, costs, deps } = graph
  const depth = new Map()
  const start = new Map()
  const finish = new Map()
  let total = 0
  for (const name of topologicalOrder(names, deps)) {
    let d = 0
    let s = 0
    for (const dep of deps.get(name)) {
      d = Math.max(d, depth.get(dep) + 1)
      s = Math.max(s, finish.get(dep))
    }
    depth.set(name, d)
    start.set(name, s)
    finish.set(name, s + costs.get(name))
    total = Math.max(total, s + costs.get(name))
  }
  return { depth, start, finish, total }
}

/**
 * The priority of each task: the cost of the longest chain that begins at it,
 * counting its own cost and the costs down to any task nothing depends on.
 */
export function priorities(graph) {
  const { names, costs, deps } = graph
  const dependents = new Map(names.map((name) => [name, []]))
  for (const name of names) {
    for (const dep of deps.get(name)) dependents.get(dep).push(name)
  }
  const priority = new Map()
  // A dependency is finished before its dependents in topological order, so
  // walking it in reverse visits every dependent first.
  for (const name of [...topologicalOrder(names, deps)].reverse()) {
    let best = 0
    for (const child of dependents.get(name)) best = Math.max(best, priority.get(child))
    priority.set(name, costs.get(name) + best)
  }
  return priority
}

/**
 * Greedy list scheduling onto `workerCount` workers. Returns the per-worker
 * run lists and the makespan.
 */
export function pack(graph, workerCount) {
  const { names, costs, deps } = graph
  const priority = priorities(graph)
  const freeAt = new Array(workerCount).fill(0)
  const runs = Array.from({ length: workerCount }, () => [])
  const finish = new Map()
  const pending = new Set(names)

  let time = 0
  let makespan = 0
  while (pending.size > 0) {
    for (;;) {
      const worker = freeAt.findIndex((at) => at <= time)
      if (worker === -1) break
      let chosen = null
      for (const name of pending) {
        const ready = deps.get(name).every((dep) => finish.has(dep) && finish.get(dep) <= time)
        if (!ready) continue
        if (
          chosen === null ||
          priority.get(name) > priority.get(chosen) ||
          (priority.get(name) === priority.get(chosen) && compareNames(name, chosen) < 0)
        ) {
          chosen = name
        }
      }
      if (chosen === null) break
      const end = time + costs.get(chosen)
      runs[worker].push({ name: chosen, start: time, finish: end })
      finish.set(chosen, end)
      freeAt[worker] = end
      pending.delete(chosen)
      if (end > makespan) makespan = end
    }
    if (pending.size === 0) break
    let next = null
    for (const at of freeAt) {
      if (at > time && (next === null || at < next)) next = at
    }
    if (next === null) break
    time = next
  }
  return { runs, makespan }
}
"}

