/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { readFileSync } from 'node:fs'
import { InputError, parseGraph } from './parse.js'
import { analyse, findCycle, pack } from './schedule.js'

const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'
const WORKERS_RE = /^[1-9][0-9]*$/

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_RE.test(argv[1])) {
      throw new InputError('error: workers must be a positive integer')
    }
    return { mode: 'pack', workers: Number(argv[1]) }
  }
  throw new InputError(USAGE)
}

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function renderWaves(graph) {
  const { depth, total } = analyse(graph)
  const waves = []
  for (const name of graph.names) {
    const d = depth.get(name)
    if (waves[d] === undefined) waves[d] = []
    waves[d].push(name)
  }
  const lines = []
  for (let k = 0; k < waves.length; k += 1) {
    lines.push(`wave ${k}: ${(waves[k] ?? []).join(' ')}`)
  }
  lines.push(`total ${total}`)
  return lines
}

function renderExplain(graph) {
  const { depth, start, finish, total } = analyse(graph)
  const lines = graph.names.map(
    (name) => `${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}`,
  )
  lines.push(`total ${total}`)
  return lines
}

function renderPack(graph, workers) {
  const { runs, makespan } = pack(graph, workers)
  const lines = runs.map(
    (runList, index) =>
      `worker ${index}:` + runList.map((r) => ` ${r.name}@${r.start}-${r.finish}`).join(''),
  )
  lines.push(`makespan ${makespan}`)
  return lines
}

function main(argv) {
  const { mode, workers } = parseArgs(argv)
  const graph = parseGraph(readStdin())
  const cycle = findCycle(graph.names, graph.deps)
  if (cycle !== null) {
    throw new InputError(`error: cycle: ${cycle.join(' -> ')}`, 3)
  }
  if (mode === 'waves') return renderWaves(graph)
  if (mode === 'explain') return renderExplain(graph)
  return renderPack(graph, workers)
}

try {
  const lines = main(process.argv.slice(2))
  process.stdout.write(lines.map((line) => `${line}\n`).join(''))
} catch (error) {
  if (error instanceof InputError) {
    process.stderr.write(`${error.message}\n`)
    process.exit(error.code)
  }
  throw error
}
"}

